const $=id=>document.getElementById(id), STORE='geburtstagsbuddy.v1';
let state={events:[],features:{zodiac:false,ascendant:false,gifts:false},giftProfiles:{},style:'Schreibe locker, herzlich, kurz und natürlich. Nicht zu kitschig.',reminderDays:3,done:{},backup:{lastBackupAt:null,lastReminderNoticeMonth:null}},activeFilter='all',calendarMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1),selectedCalendarDate=isoDate(new Date()),messageEventId=null,toastTimer;
function isoDate(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function parseDate(s){if(!s)return null;const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d,12)}
function fmtDate(d,o={day:'numeric',month:'long'}){return d.toLocaleDateString('de-DE',o)}
function load(){try{const s=JSON.parse(localStorage.getItem(STORE));if(s&&typeof s==='object')state={...state,...s};state.events=(state.events||[]).map(ev=>{if(!Object.prototype.hasOwnProperty.call(ev,'firstName')){const parts=String(ev.name||'').trim().split(/\\s+/);ev.firstName=parts.shift()||'';ev.lastName=parts.join(' ')}return ev})}catch(e){}} 
function fullName(ev){return [ev.firstName,ev.lastName].filter(Boolean).join(' ')||ev.name||''}
function greetingName(ev){return ev.firstName||String(ev.name||'').trim().split(/\\s+/)[0]||''}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state))}catch(e){toast('Speichern nicht möglich. Bitte Daten exportieren.')}}
function uid(){return 'e'+Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function nextOccurrence(ev,from=new Date()){const src=parseDate(ev.date);if(!src)return null;const today=new Date(from.getFullYear(),from.getMonth(),from.getDate(),12);let d=new Date(today.getFullYear(),src.getMonth(),src.getDate(),12);if(d<today)d=new Date(today.getFullYear()+1,src.getMonth(),src.getDate(),12);return d}
function dayDiff(a,b){return Math.round((new Date(a.getFullYear(),a.getMonth(),a.getDate())-new Date(b.getFullYear(),b.getMonth(),b.getDate()))/86400000)}
function eventLabel(ev){return ev.type==='Eigener Anlass'?(ev.customName||'Eigener Anlass'):ev.type}
function occurrenceYears(ev,d){if(ev.type==='Geburtstag'){const src=parseDate(ev.date);return src?d.getFullYear()-src.getFullYear():null}if(ev.type==='Hochzeitstag'||ev.type==='Jahrestag'){const src=parseDate(ev.date);return src?d.getFullYear()-src.getFullYear():null}return null}
function zodiacSign(date){const d=parseDate(date);if(!d)return '';const m=d.getMonth()+1,day=d.getDate();const ranges=[[1,20,'Steinbock'],[2,19,'Wassermann'],[3,21,'Fische'],[4,20,'Widder'],[5,21,'Stier'],[6,21,'Zwillinge'],[7,23,'Krebs'],[8,23,'Löwe'],[9,23,'Jungfrau'],[10,23,'Waage'],[11,22,'Skorpion'],[12,22,'Schütze']];let idx=m-1;if(day<ranges[m-1][1])idx=(m+10)%12;return ranges[idx][2]}
const zodiacSymbols={'Widder':'♈','Stier':'♉','Zwillinge':'♊','Krebs':'♋','Löwe':'♌','Jungfrau':'♍','Waage':'♎','Skorpion':'♏','Schütze':'♐','Steinbock':'♑','Wassermann':'♒','Fische':'♓'};
const ascendantMeanings={'Widder':'wirkt direkt, energiegeladen und mutig','Stier':'wirkt ruhig, beständig und genussorientiert','Zwillinge':'wirkt neugierig, kommunikativ und beweglich','Krebs':'wirkt einfühlsam, vorsichtig und fürsorglich','Löwe':'wirkt selbstbewusst, warmherzig und präsent','Jungfrau':'wirkt aufmerksam, sachlich und organisiert','Waage':'wirkt freundlich, diplomatisch und harmonieorientiert','Skorpion':'wirkt intensiv, geheimnisvoll und entschlossen','Schütze':'wirkt offen, optimistisch und freiheitsliebend','Steinbock':'wirkt ernsthaft, zuverlässig und zielorientiert','Wassermann':'wirkt unabhängig, originell und unkonventionell','Fische':'wirkt sanft, fantasievoll und empathisch'};
function calculateAscendant(date,time,lat,lon){if(!date||!time||lat===''||lon===''||!Number.isFinite(Number(lat))||!Number.isFinite(Number(lon)))return '';const d=parseDate(date),[hh,mm]=time.split(':').map(Number);if(!d||!Number.isFinite(hh)||!Number.isFinite(mm))return '';const y=d.getFullYear(),month=d.getMonth()+1,day=d.getDate();let yy=y,mo=month;if(mo<=2){yy--;mo+=12}const A=Math.floor(yy/100),B=2-A+Math.floor(A/4),jd=Math.floor(365.25*(yy+4716))+Math.floor(30.6001*(mo+1))+day+B-1524.5+(hh+mm/60)/24;const T=(jd-2451545)/36525;let gmst=280.46061837+360.98564736629*(jd-2451545)+0.000387933*T*T-T*T*T/38710000;gmst=((gmst%360)+360)%360;const lst=((gmst+Number(lon))%360+360)%360,theta=lst*Math.PI/180,phi=Number(lat)*Math.PI/180,eps=(23.439291-0.0130042*T)*Math.PI/180;let lambda=Math.atan2(-Math.cos(theta),Math.sin(eps)*Math.tan(phi)+Math.cos(eps)*Math.sin(theta));let deg=((lambda*180/Math.PI+180)%360+360)%360;const signs=['Widder','Stier','Zwillinge','Krebs','Löwe','Jungfrau','Waage','Skorpion','Schütze','Steinbock','Wassermann','Fische'];return signs[Math.floor(deg/30)]}
function astroDetails(ev){if(ev.type!=='Geburtstag')return [];const sign=zodiacSign(ev.date);let parts=[];if(state.features?.zodiac&&sign)parts.push((zodiacSymbols[sign]||'')+' '+sign);if(state.features?.ascendant){const asc=calculateAscendant(ev.date,ev.birthTime,ev.birthLat,ev.birthLon);if(asc)parts.push('↑ '+asc+' – '+ascendantMeanings[asc])}return parts}
let giftIdeaOffset=0;
function giftSearchUrl(idea,ev,budget){const terms=[idea,ev.notes||'',ev.relationship||'',budget&&budget!=='any'?'bis '+budget+' Euro':''].filter(Boolean).join(' ');return 'https://www.google.com/search?q='+encodeURIComponent(terms+' Geschenk kaufen')}
function giftAiUrl(idea,ev,budget,style){const styles={mix:'gemischt: persönlich, praktisch und Erlebnis',personal:'persönlich und emotional',practical:'praktisch und nützlich',experience:'Erlebnis und gemeinsame Zeit',surprise:'überraschend und kreativ'};const prompt='Ich suche ein Geschenk und möchte eine konkrete, fein granulierte Beratung mit aktuellen recherchierten Vorschlägen.\nGeschenkidee als Ausgangspunkt: '+idea+'\nBudget: '+(budget&&budget!=='any'?'maximal '+budget+' Euro':'noch offen; nenne verschiedene Preisstufen')+'\nGewünschter Stil: '+(styles[style]||styles.mix)+'\nBeziehung zur Person: '+(ev.relationship||'nicht angegeben')+'\nPersönliche Infos, Interessen und Hobbys: '+(String(ev.notes||'').trim()||'keine weiteren Angaben')+'\nBitte schlage 5 konkrete passende Geschenke vor. Erkläre jeweils kurz, warum es zur Person passt, nenne realistische aktuelle Preise und wenn möglich konkrete Produkte/Marken sowie seriöse Kauf- oder Informationslinks. Bleibe innerhalb des Budgets, kennzeichne Unsicherheiten und erfinde keine Verfügbarkeiten. Wenn die Angaben nicht reichen, stelle zuerst höchstens 2 gezielte Rückfragen.';return 'https://www.google.com/search?udm=50&q='+encodeURIComponent(prompt)}

